public Resultado Renomear(string documentoId, string novoNome)
{
    var documento = _documentos.FirstOrDefault(d => d.Id == documentoId);   // linha 1

    var nomeAtual = documento?.Nome ?? "sem nome";                          // linha 2

    documento.Nome = novoNome;                                              // linha 3
    return Resultado.Ok($"{nomeAtual} → {novoNome}");
}
